// Función de autenticación oficial por Usuario y Contraseña
// Regla: Usuario = Primer Nombre y Primer Apellido
//        Contraseña = Lo mismo todo junto con minúscula
function authenticateParticipant(usernameInput, passwordInput) {
  if (!usernameInput || !passwordInput) {
    return { success: false, message: 'Por favor ingresa usuario y contraseña.' };
  }

  function cleanStr(s) {
    return (s || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '');
  }

  const uClean = cleanStr(usernameInput);
  const pClean = cleanStr(passwordInput);

  if (!uClean || !pClean) {
    return { success: false, message: 'Ingresa un usuario y contraseña válidos.' };
  }

  // Accesos Especiales Oficiales y Provisionales
  if (uClean === 'melaniealmeyda' && pClean === 'melaniealmeyda') {
    return {
      success: true,
      student: {
        name: 'Melanie Almeyda',
        shortName: 'Melanie Almeyda',
        email: 'melanie@polyglotmap.com',
        role: 'Directora / Administradora Polyglot Map',
        passportNo: 'PM-VIP-001',
        allowedCourses: [
          'bootcamp-portugues-cero',
          'bootcamp-portugues-basico2',
          'bootcamp-ingles-cero',
          'club-ingles-a2',
          'bootcamp-master-classes'
        ]
      }
    };
  }

  if ((uClean === 'viajero2026' || uClean === 'viajero') && (pClean === 'viajero2026' || pClean === 'viajero')) {
    return {
      success: true,
      student: {
        name: 'Viajero Polyglot Map',
        shortName: 'Viajero 2026',
        email: 'viajero2026@polyglotmap.com',
        role: 'Viajero Provisional',
        passportNo: 'PM-2026',
        allowedCourses: [
          'bootcamp-portugues-cero',
          'bootcamp-portugues-basico2',
          'bootcamp-ingles-cero',
          'club-ingles-a2'
        ]
      }
    };
  }

  // Regla 1: La contraseña debe ser lo mismo que el usuario todo junto en minúscula
  if (uClean !== pClean) {
    return {
      success: false,
      message: 'La contraseña debe ser tu usuario todo junto en minúscula (ej: usuario "Lucía Mendoza" -> contraseña "luciamendoza").'
    };
  }

  // Buscar en la base de datos de estudiantes registrados (Inscritos exclusivamente a Portugués)
  const match = STUDENTS_DATABASE.find(st => {
    if (st.p === pClean) return true;
    if (st.k && st.k.includes(pClean)) return true;
    if (cleanStr(st.u) === uClean) return true;
    if (cleanStr(st.n) === uClean) return true;
    if (cleanStr(st.e) === uClean) return true;
    return false;
  });

  if (match) {
    return {
      success: true,
      student: {
        name: match.n,
        shortName: match.u,
        email: match.e,
        role: 'Estudiante Inscrito · Portugués',
        passportNo: 'PM-' + Math.abs(match.n.split('').reduce((a, b) => ((a << 5) - a) + b.charCodeAt(0), 0) % 9000 + 1000),
        allowedCourses: [
          'bootcamp-portugues-cero',
          'bootcamp-portugues-basico2'
        ]
      }
    };
  }

  // Si cumple el formato de primer nombre y apellido (al menos 2 palabras)
  const words = usernameInput.trim().split(/\s+/);
  if (words.length >= 2 && uClean === pClean && uClean.length >= 5) {
    const capitalized = words.map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
    return {
      success: true,
      student: {
        name: capitalized,
        shortName: words.slice(0, 2).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' '),
        email: uClean + '@polyglotmap.com',
        role: 'Estudiante Inscrito · Portugués',
        passportNo: 'PM-' + Math.floor(1000 + Math.random() * 9000),
        allowedCourses: [
          'bootcamp-portugues-cero',
          'bootcamp-portugues-basico2'
        ]
      }
    };
  }

  return {
    success: false,
    message: 'Usuario no encontrado en la lista de inscritos. Verifica que coincida con tu primer nombre y primer apellido registrado.'
  };
}

if (typeof window !== 'undefined') {
  window.STUDENTS_DATABASE = STUDENTS_DATABASE;
  window.authenticateParticipant = authenticateParticipant;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { STUDENTS_DATABASE, authenticateParticipant };
}
